module FinancingStudy version "1";
use DemoDebt version "1";
source disclosure = external("synthetic-note-7");
entity Beta functional USD;
book Statutory entity Beta basis DemoDebt version "1";
account Cash : Asset book Statutory;
account Debt : Liability book Statutory;
account InterestExpense : Expense book Statutory;
account Retained : Equity book Statutory;
opening carried for Statutory from external("after-2025-close");
observation borrowing : Money<USD> instant @2025-12-31 = 100 USD from disclosure;
symbol share : Real in [0, 1] because "Fixed-rate proportion not disclosed";
contract facility : DebtMix book Statutory {
  principal = value(borrowing);
  fixed_fraction = share;
  fixed_rate = 0.05 per year;
  initial_floating_rate = 0.05 per year;
}
alternative fixed { assume share == 1; }
alternative floating { assume share == 0; }
scenario shock { set market_rate = constant(0.07 per year); }
report financials for Statutory { mapping = external("DemoDebt.statements.v1"); }

